void validateVisualSources(const QJsonObject&scene,const QString& question,const QString& quote){validateVisualDetail(scene,question);bool dataLayout=false;for(auto object:scene["objects"].toArray())dataLayout|=QStringList{"grid","chart","math"}.contains(object.toObject()["kind"].toString());if(dataLayout&&!scene["relations"].toArray().isEmpty())need(QRegularExpression("\\b(arrow|annotate|connect|relationship|link)\\w*\\b",QRegularExpression::CaseInsensitiveOption).match(question).hasMatch(),"visual-unrequested-relations");validateVisualQuestion(scene,question);auto canonical=[](QString s){s.replace(QChar(0x00b2),"^2");s.replace(QChar(0x00b3),"^3");s.replace(QChar(0x2212),"-");s.replace(QChar(0x00d7),"*");s.replace(QChar(0x03c0),"pi");s.remove(QRegularExpression("\\s+"));return s.toLower();};auto formula=QRegularExpression("\\by\\s*=\\s*([^\\n;?!,]+)",QRegularExpression::CaseInsensitiveOption).match(question);if(formula.hasMatch()){auto expression=formula.captured(1).trimmed();expression=expression.split(QRegularExpression("\\s+(?:for|from|with|over|on|where|between)\\b",QRegularExpression::CaseInsensitiveOption)).first().trimmed();if(expression.endsWith('.'))expression.chop(1);bool found=false;for(auto value:scene["objects"].toArray()){auto o=value.toObject();if(o["kind"]=="math"){found=true;need(canonical(o["content"].toObject()["expression"].toString())==canonical(expression));}}need(found);}QMap<QString,QSet<QString>> includedAcross;for(auto value:scene["datasets"].toArray()){auto d=value.toObject();auto source=d["source"].toString();if(source.startsWith("reference:"))continue;bool chart=false,geographic=false;for(auto value:scene["objects"].toArray()){auto o=value.toObject();if(o["content"].toObject()["data"]!=d["id"])continue;chart|=o["kind"]=="chart";geographic|=o["kind"]=="map"&&o["content"].toObject()["projection"]=="equirectangular";}if(!chart&&!geographic)continue;if(source=="illustrative"){need(QRegularExpression("\\b(example|sample|hypothetical|illustrative)\\b",QRegularExpression::CaseInsensitiveOption).match(question).hasMatch());continue;}need(source=="question"||source=="context");const auto data=source=="question"?question:quote;need(data.size()<=16000&&!data.isEmpty());auto& included=includedAcross[source];auto literal=literalData(data);if(!literal.isEmpty()){auto rows=d["rows"].toArray();need(rows.size()==literal.size());for(int i=0;i<rows.size();++i){auto row=rows[i].toObject();need(row["label"].toString()==QString::number(i+1));included.insert(row["label"].toString());if(literal[i].isDouble())need(!geographic&&row["y"]==literal[i]&&(row["x"].isNull()||row["x"].toDouble()==i+1));else{auto pair=literal[i].toArray();need(row["x"]==pair[0]&&row["y"]==pair[1]);}}continue;}for(auto value:d["rows"].toArray()){auto row=value.toObject();auto label=row["label"].toString();need(!label.isEmpty());included.insert(label);auto escaped=QRegularExpression::escape(label);auto scalar=QRegularExpression(escaped+"\\s*[:=]\\s*"+numeric+"(?![0-9.eE])").match(data);auto pair=QRegularExpression(escaped+"\\s*[:=]\\s*\\(?\\s*"+numeric+"\\s*,\\s*"+numeric+"\\s*\\)?").match(data);bool xy=!row["x"].isNull()&&pair.hasMatch();need(xy?(same(pair,1,row["x"].toDouble())&&same(pair,2,row["y"].toDouble())):!geographic&&same(scalar,1,row["y"].toDouble()));}}for(auto source:includedAcross.keys()){const auto data=source=="question"?question:quote;const auto& included=includedAcross[source];auto pairs=QRegularExpression("(?:^|[,;\\n:])\\s*([\\p{L}\\p{N}][\\p{L}\\p{N} _.-]{0,63}?)\\s*[:=]\\s*"+numeric+"(?![0-9.eE])").globalMatch(data);while(pairs.hasNext()){auto m=pairs.next();need(included.contains(m.captured(1).trimmed()));}}}
